-- FORME D1 schema and starter catalogue. Re-running this file resets all store data.
DROP TABLE IF EXISTS analytics; DROP TABLE IF EXISTS payments; DROP TABLE IF EXISTS posts; DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS order_items; DROP TABLE IF EXISTS orders; DROP TABLE IF EXISTS customers; DROP TABLE IF EXISTS products; DROP TABLE IF EXISTS categories;
CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE products(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category_id INTEGER NOT NULL REFERENCES categories(id),price INTEGER NOT NULL CHECK(price>=0),compare_at_price INTEGER,image_url TEXT NOT NULL,sizes_json TEXT NOT NULL DEFAULT '[]',colors_json TEXT NOT NULL DEFAULT '[]',stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),featured INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL UNIQUE,email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id TEXT PRIMARY KEY,order_number TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL REFERENCES customers(id),address TEXT NOT NULL,notes TEXT,subtotal INTEGER NOT NULL,shipping INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),product_name TEXT NOT NULL,size TEXT,color TEXT,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL,line_total INTEGER NOT NULL);
CREATE INDEX idx_products_category ON products(category_id,active); CREATE INDEX idx_products_featured ON products(featured,active); CREATE INDEX idx_orders_created ON orders(created_at DESC); CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE TRIGGER prevent_negative_stock BEFORE UPDATE OF stock ON products WHEN NEW.stock<0 BEGIN SELECT RAISE(ABORT,'Not enough stock'); END;
